(() => {
  const photos = [
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,"
];
  const previews = document.querySelectorAll('.portfolio-photos img');
  const key = 'homepage-portfolio-photos';
  let previous = '';
  try {
    previous = localStorage.getItem(key) || '';
  } catch {
    // Local previews can run without storage.
  }
  let selected;
  let signature;
  do {
    const pool = photos.slice();
    selected = Array.from(previews, () => pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
    signature = selected.slice().sort().join('|');
  } while (signature === previous);

  previews.forEach((image, index) => { image.src = selected[index]; });
  try {
    localStorage.setItem(key, signature);
  } catch {
    // The current selection still works without storage.
  }
})();
